// ========================================================================================================================================
// ======================= RGB Effects Engine (Doorlock strip + Matrix) ========================
// ========================================================================================================================================

uint32_t hueColor(uint16_t hue, uint8_t val = 255) {              // HUE_* -> RGB888, for alerts
  return pixels.gamma32(pixels.ColorHSV(hue, 255, val));
}

uint32_t miredsToColor(uint16_t mireds) {

  float kelvin = (1000000.0f / mireds) / 100.0f;
  float r, g, b;

  if(kelvin <= 66) 
  {
    r = 255;
    g = 99.47f * logf(kelvin) - 161.12f;
  } 
  else 
  {
    r = 329.7f * powf(kelvin - 60, -0.1332f);
    g = 288.12f * powf(kelvin - 60, -0.0755f);
  }

  if(kelvin >= 66) b = 255;
  else if(kelvin <= 19) b = 0;
  else b = 138.52f * logf(kelvin - 10) - 305.04f;

  r = constrain(r, 0, 255);
  g = constrain(g, 0, 255);
  b = constrain(b, 0, 255);

  return ((uint32_t)(uint8_t)r << 16) | ((uint32_t)(uint8_t)g << 8) | (uint8_t)b;
}

uint16_t matrixXY(uint8_t x, uint8_t y) {
  if(MATRIX_SERPENTINE && (y % 2 == 1)) x = (MATRIX_W - 1) - x;
  uint8_t localIndex = y * MATRIX_W + x;
  return Matrix_LEDS[localIndex];
}

class StripEffects {
  public:
    void begin(const int* leds, uint8_t count)
    {
      _leds = leds;
      _count = count;
    }

    // Matrix: pass an (x,y) -> pixel-index function for the spatial effects (Circular etc).
    void begin2D(const int* leds, uint8_t count, uint8_t w, uint8_t h, uint16_t (*xyFunc)(uint8_t, uint8_t))
    {
      begin(leds, count);
      _width = w;
      _height = h;
      _xyFunc = xyFunc;
    }

    // Doorlock: declares the strip as a loop made of two equal-length sides (see note at
    // the top of this file about which physical end is assumed to be index 0).
    void beginLoopSides(const int* leds, uint8_t count, uint8_t sideLen)
    {
      begin(leds, count);
      _sideLen = sideLen;
    }

    void setPower(bool on)
    {
      _on = on;
      if(!on) clear();
      else if(_effect == 0 && !alertActive()) renderSolid();
    }

    void setBrightness(uint8_t percent)
    {
      _brightnessPct = percent;
      if(_on && _effect == 0 && !alertActive()) renderSolid();
    }

    void setColor(uint32_t rgb)
    {
      _color = rgb;
      if(_on && _effect == 0 && !alertActive()) renderSolid();
    }

    void setEffect(uint8_t idx)
    {
      _effect = idx;
      resetMotion();
      if(_on && _effect == 0 && !alertActive()) renderSolid();
    }

    // ---- Alerts: a short, higher-priority pattern that plays over whatever the strip is
    // currently doing (even if it's off), then automatically restores it. ----

    void alertFlash(uint32_t color, uint8_t times, uint16_t onMs = 120, uint16_t offMs = 120)
    {
      startAlert(ALERT_FLASH, color, (uint32_t)times * (onMs + offMs));
      _alertOnMs = onMs;
      _alertOffMs = offMs;
    }

    void alertPulse(uint32_t color, uint16_t durationMs)
    {
      startAlert(ALERT_PULSE, color, durationMs);
    }

    void alertSweep(uint32_t color, uint16_t durationMs)
    {
      startAlert(ALERT_SWEEP, color, durationMs);
    }

    void stopAlert()
    {
      if(_alertKind == ALERT_NONE) return;
      _alertKind = ALERT_NONE;
      restoreAmbient();
    }

    bool alertActive() const { return _alertKind != ALERT_NONE; }

    // Call every loop(). Self-throttled to FRAME_MS - calling it more often costs nothing.
    void update()
    {
      unsigned long now = millis();
      if(now - _lastFrame < FRAME_MS) return;
      _lastFrame = now;

      if(_alertKind != ALERT_NONE) { renderAlert(now); return; }
      if(!_on || _effect == 0) return;                 // solid colour is rendered on-demand, not per-frame

      switch(_effect)
      {
        case 1:  effectBreathe();  break;
        case 2:  effectRainbow();  break;
        case 3:  effectChase();    break;
        case 4:  effectTheater();  break;
        case 5:  effectComet();    break;
        case 6:  effectTwinkle();  break;
        case 7:  effectSparkle();  break;
        case 8:  effectWipe();     break;
        case 9:  effectBounce();   break;
        case 10: effectWheel();    break;
        case 11: effectFire();     break;
        case 12: effectStrobe();   break;
        case 13: effectWave();     break;
        // 14-16 mean different things on each strip, depending on which geometry it was
        // begin()-ed with - harmless, since a strip only ever receives indices from its
        // own HASelect option list.
        case 14: if(_xyFunc) effectCircularSpatial(); else if(_sideLen) effectBeam();       break;
        case 15: if(_xyFunc) effectTopDownSpatial();  else if(_sideLen) effectRotateDual(); break;
        case 16: if(_xyFunc) effectLeftRightSpatial();                                      break;
        default: break;
      }
      pixels.show();
    }

  private:
    static const uint16_t FRAME_MS = 25;                // ~40 fps cap, shared by ambient + alerts

    const int* _leds = nullptr;
    uint8_t _count = 0;
    uint8_t _width = 0, _height = 0;
    uint16_t (*_xyFunc)(uint8_t, uint8_t) = nullptr;
    uint8_t _sideLen = 0;                                // doorlock: LEDs per side of the loop

    bool _on = false;
    uint8_t _brightnessPct = 100;
    uint32_t _color = 0xFFFFFF;
    uint8_t _effect = 0;

    uint16_t _step = 0;
    int8_t _dir = 1;
    unsigned long _lastStep = 0;
    unsigned long _lastFrame = 0;
    unsigned long _effectStartTime = 0;   // every continuous (non-stepped) effect's time origin,
                                           // so selecting an effect always starts it from the same
                                           // recognisable state instead of a random mid-cycle point
    float _glow[26] = {0};

    enum AlertKind : uint8_t { ALERT_NONE, ALERT_FLASH, ALERT_PULSE, ALERT_SWEEP };
    AlertKind _alertKind = ALERT_NONE;
    uint32_t _alertColor = 0;
    unsigned long _alertStart = 0;
    uint32_t _alertDuration = 0;
    uint16_t _alertOnMs = 0, _alertOffMs = 0;

    // ---- small shared helpers ----

    uint32_t applyBrightness(uint32_t rgb, float factor)
    {
      if(factor < 0) factor = 0;
      if(factor > 1) factor = 1;
      uint8_t r = (uint8_t)(((rgb >> 16) & 0xFF) * factor);
      uint8_t g = (uint8_t)(((rgb >> 8) & 0xFF) * factor);
      uint8_t b = (uint8_t)((rgb & 0xFF) * factor);
      return pixels.Color(r, g, b);
    }

    void clear()
    {
      for(uint8_t i = 0; i < _count; i++) pixels.setPixelColor(_leds[i], 0);
      pixels.show();
    }

    void renderSolid()
    {
      uint32_t c = applyBrightness(_color, _brightnessPct / 100.0f);
      for(uint8_t i = 0; i < _count; i++) pixels.setPixelColor(_leds[i], c);
      pixels.show();
    }

    void resetMotion()
    {
      _step = 0;
      _dir = 1;
      for(uint8_t i = 0; i < _count; i++) _glow[i] = 0;
      _lastStep = millis();
      _lastFrame = 0;
      _effectStartTime = millis();
    }

    bool advanceStepMod(uint16_t intervalMs, uint16_t mod)
    {
      if(millis() - _lastStep >= intervalMs)
      {
        _lastStep = millis();
        _step = (_step + 1) % mod;
        return true;
      }
      return false;
    }

    // Doorlock geometry: which side (0/1) and how far up it (0 = bottom, sideLen-1 = top)
    // a loop index represents. See the ASSUMPTION note at the top of this file.
    void sideHeight(uint8_t i, uint8_t &side, uint8_t &height) const
    {
      if(i < _sideLen) { side = 0; height = i; }
      else             { side = 1; height = (uint8_t)(_count - 1 - i); }
    }

    uint8_t spatialMaxRing()
    {
      uint8_t cx = (_width - 1) / 2;
      uint8_t cy = (_height - 1) / 2;
      uint8_t rx = max(cx, (uint8_t)(_width - 1 - cx));
      uint8_t ry = max(cy, (uint8_t)(_height - 1 - cy));
      return max(rx, ry);
    }

    void decayAndRenderSpatial()
    {
      for(uint8_t y = 0; y < _height; y++)
        for(uint8_t x = 0; x < _width; x++)
        {
          uint8_t idx = y * _width + x;
          float b = _glow[idx];
          if(b > 0) { b *= 0.80f; if(b < 0.004f) b = 0; _glow[idx] = b; }
          pixels.setPixelColor(_xyFunc(x, y), applyBrightness(_color, b * (_brightnessPct / 100.0f)));
        }
    }

    // ---- alerts ----

    void startAlert(AlertKind kind, uint32_t color, uint32_t durationMs)
    {
      _alertKind = kind;
      _alertColor = color;
      _alertStart = millis();
      _alertDuration = durationMs;
      _lastFrame = 0;                                   // render the first alert frame immediately
    }

    void restoreAmbient()
    {
      if(_on) { if(_effect == 0) renderSolid(); else _lastFrame = 0; }  // else: next update() redraws it
      else clear();
    }

    void renderAlert(unsigned long now)
    {
      unsigned long elapsed = now - _alertStart;
      if(elapsed >= _alertDuration) { _alertKind = ALERT_NONE; restoreAmbient(); return; }

      switch(_alertKind)
      {
        case ALERT_FLASH:
        {
          uint16_t cyc = (uint16_t)(elapsed % (_alertOnMs + _alertOffMs));
          uint32_t c = (cyc < _alertOnMs) ? _alertColor : 0;
          for(uint8_t i = 0; i < _count; i++) pixels.setPixelColor(_leds[i], c);
          break;
        }
        case ALERT_PULSE:
        {
          float phase = (float)elapsed / _alertDuration;           // 0..1 across the whole alert
          float s = sinf(phase * PI);                              // smooth up, then back down to 0
          uint32_t c = applyBrightness(_alertColor, s);
          for(uint8_t i = 0; i < _count; i++) pixels.setPixelColor(_leds[i], c);
          break;
        }
        case ALERT_SWEEP:
        {
          float phase = (float)elapsed / _alertDuration;           // 0..1, one full lap of the strip
          float headF = phase * _count;
          for(uint8_t i = 0; i < _count; i++)
          {
            float d = headF - i; if(d < 0) d += _count;
            float b = (d < 4.0f) ? (1.0f - d / 4.0f) : 0.0f;        // short bright head + soft tail
            pixels.setPixelColor(_leds[i], applyBrightness(_alertColor, b));
          }
          break;
        }
        default: break;
      }
      pixels.show();
    }

    // ---- ambient effects (indices 1-13, shared by both strips) ----

    void effectBreathe()
    {
      float phase = ((millis() - _effectStartTime) % 4000) / 4000.0f;
      float s = (sinf(phase * 2 * PI) + 1.0f) / 2.0f;
      float factor = (0.15f + 0.85f * s) * (_brightnessPct / 100.0f);
      uint32_t c = applyBrightness(_color, factor);
      for(uint8_t i = 0; i < _count; i++) pixels.setPixelColor(_leds[i], c);
    }

    void effectRainbow()
    {
      unsigned long t = millis() - _effectStartTime;
      uint8_t val = (uint8_t)(255 * (_brightnessPct / 100.0f));
      for(uint8_t i = 0; i < _count; i++)
      {
        uint16_t hue = (uint16_t)(((uint32_t)i * 65536UL / _count) + t * 20);
        pixels.setPixelColor(_leds[i], pixels.gamma32(pixels.ColorHSV(hue, 255, val)));
      }
    }

    // Crisp 3-LED head chasing around the loop (was a single pixel - easy to miss and
    // visually identical to Bounce).
    void effectChase()
    {
      advanceStepMod(70, _count);
      uint32_t c = applyBrightness(_color, _brightnessPct / 100.0f);
      for(uint8_t i = 0; i < _count; i++)
      {
        int d = (int)i - (int)_step; if(d < 0) d += _count;
        pixels.setPixelColor(_leds[i], (d < 3) ? c : 0);
      }
    }

    void effectTheater()
    {
      advanceStepMod(150, 3);
      uint32_t c = applyBrightness(_color, _brightnessPct / 100.0f);
      for(uint8_t i = 0; i < _count; i++) pixels.setPixelColor(_leds[i], ((i % 3) == _step) ? c : 0);
    }

    void effectComet()
    {
      advanceStepMod(60, _count);
      _glow[_step] = 1.0f;
      for(uint8_t i = 0; i < _count; i++)
      {
        if(_glow[i] > 0) { _glow[i] *= 0.80f; if(_glow[i] < 0.01f) _glow[i] = 0; }
        pixels.setPixelColor(_leds[i], applyBrightness(_color, _glow[i] * (_brightnessPct / 100.0f)));
      }
    }

    void effectTwinkle()
    {
      if(millis() - _lastStep > 90) { _lastStep = millis(); _glow[random(_count)] = 1.0f; }
      for(uint8_t i = 0; i < _count; i++)
      {
        if(_glow[i] > 0) { _glow[i] *= 0.90f; if(_glow[i] < 0.02f) _glow[i] = 0; }
        pixels.setPixelColor(_leds[i], applyBrightness(_color, _glow[i] * (_brightnessPct / 100.0f)));
      }
    }

    void effectSparkle()
    {
      if(millis() - _lastStep > 50) { _lastStep = millis(); if(random(100) < 40) _glow[random(_count)] = 1.0f; }
      for(uint8_t i = 0; i < _count; i++)
      {
        if(_glow[i] > 0) { _glow[i] *= 0.65f; if(_glow[i] < 0.03f) _glow[i] = 0; }
        pixels.setPixelColor(_leds[i], applyBrightness(_color, _glow[i] * (_brightnessPct / 100.0f)));
      }
    }

    // Doorlock: both sides fill from the bottom at once, like water rising, then drain.
    // Matrix / anything without side geometry: falls back to the old plain index wipe.
    void effectWipe()
    {
      if(_sideLen)
      {
        advanceStepMod(70, 2 * _sideLen);
        bool filling = _step < _sideLen;
        int litTo = filling ? _step : (int)(2 * _sideLen - 1 - _step);
        uint32_t c = applyBrightness(_color, _brightnessPct / 100.0f);
        for(uint8_t i = 0; i < _count; i++)
        {
          uint8_t side, h; sideHeight(i, side, h);
          pixels.setPixelColor(_leds[i], ((int)h <= litTo) ? c : 0);
        }
      }
      else
      {
        advanceStepMod(80, _count * 2);
        uint32_t c = applyBrightness(_color, _brightnessPct / 100.0f);
        bool filling = _step < _count;
        int litUpTo = filling ? _step : (2 * (int)_count - 1 - _step);
        for(uint8_t i = 0; i < _count; i++) pixels.setPixelColor(_leds[i], ((int)i <= litUpTo) ? c : 0);
      }
    }

    void effectBounce()
    {
      if(millis() - _lastStep > 60)
      {
        _lastStep = millis();
        _step += _dir;
        if(_step >= _count - 1) { _step = _count - 1; _dir = -1; }
        if(_step <= 0) { _step = 0; _dir = 1; }
      }
      uint32_t c = applyBrightness(_color, _brightnessPct / 100.0f);
      for(uint8_t i = 0; i < _count; i++) pixels.setPixelColor(_leds[i], (i == _step) ? c : 0);
    }

    // FIXED: was advancing so slowly (~22 min per cycle) it looked dead. ~6s/cycle now.
    void effectWheel()
    {
      uint16_t hue = (uint16_t)(((millis() - _effectStartTime) * 11) % 65536);
      uint32_t c = pixels.gamma32(pixels.ColorHSV(hue, 255, (uint8_t)(255 * (_brightnessPct / 100.0f))));
      for(uint8_t i = 0; i < _count; i++) pixels.setPixelColor(_leds[i], c);
    }

    void effectFire()
    {
      if(millis() - _lastStep > 60)
      {
        _lastStep = millis();
        for(uint8_t i = 0; i < _count; i++)
        {
          int cooldown = random(0, 80);
          int heat255 = (int)(_glow[i] * 255) - cooldown;
          _glow[i] = (heat255 < 0 ? 0 : heat255) / 255.0f;
        }
        if(random(100) < 60)
        {
          uint8_t idx = random(_count);
          float spark = random(60, 100) / 100.0f;
          _glow[idx] = min(1.0f, _glow[idx] + spark);
        }
      }
      for(uint8_t i = 0; i < _count; i++)
      {
        float heat = _glow[i];
        uint16_t hue = (uint16_t)(1500 + heat * 3500);
        uint8_t val = (uint8_t)(heat * 255 * (_brightnessPct / 100.0f));
        pixels.setPixelColor(_leds[i], val == 0 ? 0 : pixels.gamma32(pixels.ColorHSV(hue, 255, val)));
      }
    }

    void effectStrobe()
    {
      bool on = (millis() % 300) < 40;
      uint32_t c = on ? applyBrightness(_color, _brightnessPct / 100.0f) : 0;
      for(uint8_t i = 0; i < _count; i++) pixels.setPixelColor(_leds[i], c);
    }

    void effectWave()
    {
      float t = (millis() - _effectStartTime) / 1000.0f;
      for(uint8_t i = 0; i < _count; i++)
      {
        float phase = (float)i / _count * 2 * PI * 2 + t * 2.5f;     // 2 crests around the loop
        float s = (sinf(phase) + 1.0f) / 2.0f;
        pixels.setPixelColor(_leds[i], applyBrightness(_color, s * (_brightnessPct / 100.0f)));
      }
    }

    // FIXED: was 2 discrete steps on a 3x3 grid (dot, then ring - all a 3x3 CAN show with
    // hard steps), so it read as a blink, not a circle. Continuous soft ripple instead.
    void effectCircularSpatial()
    {
      // A ripple of brightness travels outward from the centre on a repeating cycle. The
      // distance-to-phase gap is computed WITH WRAPAROUND (fmodf back into [0,period)) so the
      // ripple for ring 0 also catches the END of the cycle, just before it restarts - without
      // that, there's a stretch of every cycle where nothing is lit at all (verified by tracing
      // actual brightness values over a full cycle before and after this fix).
      uint8_t maxRing = spatialMaxRing();
      float period = maxRing + 1.6f;                      // tight enough that rings' glow overlaps, no gap
      float phase = fmodf((millis() - _effectStartTime) / 450.0f, period);
      uint8_t cx = (_width - 1) / 2, cy = (_height - 1) / 2;
      for(uint8_t y = 0; y < _height; y++)
        for(uint8_t x = 0; x < _width; x++)
        {
          uint8_t dist = max(abs((int)x - (int)cx), abs((int)y - (int)cy));
          // shortest circular distance between phase and dist, wrapping either direction -
          // without checking BOTH directions, the outermost ring never hands off smoothly
          // back to the centre and there's a dark gap once per cycle (confirmed by tracing).
          float dRaw = fmodf(phase - dist, period); if(dRaw < 0) dRaw += period;
          float d = min(dRaw, period - dRaw);
          float b = (d < 1.3f) ? (1.0f - d / 1.3f) : 0.0f;
          pixels.setPixelColor(_xyFunc(x, y), applyBrightness(_color, b * (_brightnessPct / 100.0f)));
        }
    }

    // FIXED (two bugs): (1) direction inverted per request - the row that lights first is
    // now _step instead of height-1-_step. (2) advanceStepMod() increments _step BEFORE
    // returning, so the old "only light the row when the step just changed" pattern lit rows
    // 1,2,...  but skipped row 0 entirely on every activation (confirmed by tracing - row 0
    // never appeared). Now the current row is rendered every frame regardless of whether it
    // just advanced, which also holds each row solid for its full dwell time instead of a
    // single-frame flash that immediately starts fading.
    void effectTopDownSpatial()
    {
      advanceStepMod(200, _height);
      for(uint8_t x = 0; x < _width; x++) _glow[_step * _width + x] = 1.0f;
      decayAndRenderSpatial();
    }

    void effectLeftRightSpatial()
    {
      advanceStepMod(200, _width);
      for(uint8_t y = 0; y < _height; y++) _glow[y * _width + _step] = 1.0f;
      decayAndRenderSpatial();
    }

    // ---- doorlock-only effects (need beginLoopSides) ----

    // NEW: a bar travels from the bottom to the top on both sides together, then back
    // down - "beaming up and down".
    void effectBeam()
    {
      const uint8_t BEAM_LEN = 4;
      if(millis() - _lastStep > 35)
      {
        _lastStep = millis();
        _step += _dir;
        if(_step >= _sideLen - 1) { _step = _sideLen - 1; _dir = -1; }
        if(_step <= 0)            { _step = 0; _dir = 1; }
      }
      for(uint8_t i = 0; i < _count; i++)
      {
        uint8_t side, h; sideHeight(i, side, h);
        int d = (int)h - (int)_step; if(d < 0) d = -d;
        float b = (d < BEAM_LEN) ? (1.0f - (float)d / BEAM_LEN) : 0.0f;
        pixels.setPixelColor(_leds[i], applyBrightness(_color, b * (_brightnessPct / 100.0f)));
      }
    }

    // NEW: two chase heads, always exactly half the loop apart.
    void effectRotateDual()
    {
      advanceStepMod(70, _count);
      uint32_t c = applyBrightness(_color, _brightnessPct / 100.0f);
      uint8_t half = _count / 2;
      for(uint8_t i = 0; i < _count; i++)
      {
        int d1 = (int)i - (int)_step; if(d1 < 0) d1 += _count;
        int d2 = (int)i - (int)((_step + half) % _count); if(d2 < 0) d2 += _count;
        pixels.setPixelColor(_leds[i], (d1 < 3 || d2 < 3) ? c : 0);
      }
    }
};

