static bool KeypadIRQ_Find(char ch, byte &row, byte &col) {
  for (byte r = 0; r < KEY_ROWS; r++)
    for (byte c = 0; c < KEY_COLS; c++)
      if (keyMap[r][c] == ch) { row = rowPins[r]; col = colPins[c]; return true; }
  return false;
}

static void KeypadIRQ_ForceIdle(char ch) {
  for (byte i = 0; i < LIST_MAX; i++)
  {
    if (keypad.key[i].kchar == ch)
    {
      keypad.key[i].kstate = IDLE;
      keypad.key[i].kchar = NO_KEY;
      keypad.key[i].kcode = -1;
      keypad.key[i].stateChanged = false;
    }
  }
}

void KeypadIRQ_GoIdleWatch() {
  for (byte c = 0; c < KEY_COLS; c++)
    ExtraIO.pinMode(colPins[c], OUTPUT, LOW);
  for (byte r = 0; r < KEY_ROWS; r++)
  {
    ExtraIO.pinMode(rowPins[r], INPUT_PULLUP);
    ExtraIO.enableInterrupt(rowPins[r], CHANGE);
  }
  uint16_t discard;
  ExtraIO.getAndClearInterrupts(&discard);
  kp_state = KP_IDLE_WATCH;
}

static void KeypadIRQ_GoReleaseWatch(byte row, byte col) {
  for (byte c = 0; c < KEY_COLS; c++)
  {
    if (colPins[c] == col) ExtraIO.pinMode(colPins[c], OUTPUT, LOW);
    else                   ExtraIO.pinMode(colPins[c], INPUT);   // floating: can't pull any row low
  }
  for (byte r = 0; r < KEY_ROWS; r++)
  {
    if (rowPins[r] == row) ExtraIO.enableInterrupt(rowPins[r], RISING);
    else                   ExtraIO.disableInterrupt(rowPins[r]);
  }
  uint16_t discard;
  ExtraIO.getAndClearInterrupts(&discard);
  kp_state = KP_RELEASE_WATCH;
}

void KeypadIRQ_OnInterrupt(uint16_t src) {
  if(!(src & ROW_MASK)) return;

  if(kp_state == KP_IDLE_WATCH)
  {
    for (byte c = 0; c < KEY_COLS; c++) ExtraIO.pinMode(colPins[c], INPUT);
    kp_state = KP_ACTIVE_POLL;     // something is down; find out what on the next loop() pass
    kp_last_poll = 0;
    kp_active_since = millis();
  }
  else if (kp_state == KP_RELEASE_WATCH)
  {
    DEBUG_PRINTLN("KeypadIRQ - '*' released");
    Outdoor_Beep(100);
    TransmitAudioBTNHeld = false;
    KeypadIRQ_ForceIdle('*');
    KeypadIRQ_GoIdleWatch();
  }
}

void KeypadIRQ_Loop() {
  if (kp_state != KP_ACTIVE_POLL) return;
  if (millis() - kp_last_poll < 25) return;
  kp_last_poll = millis();

  keypad.getKeys();

  if (TransmitAudioBTNHeld)
  {
    byte row, col;
    if (KeypadIRQ_Find('*', row, col))
    {
      KeypadIRQ_GoReleaseWatch(row, col);
      uint16_t in;
      if(ExtraIO.getInputs(&in) && (in & (1u << row)))
      {
        DEBUG_PRINTLN("KeypadIRQ - '*' was already released by the time the watch was armed");
        TransmitAudioBTNHeld = false;
        KeypadIRQ_ForceIdle('*');
        KeypadIRQ_GoIdleWatch();
      }
    }
    return;
  }

  bool anyDown = false;
  for (byte i = 0; i < LIST_MAX; i++)
    if (keypad.key[i].kstate != IDLE) anyDown = true;
  if (!anyDown && millis() - kp_active_since >= KP_SETTLE_MS) KeypadIRQ_GoIdleWatch();
}

void IO_Configure() {
  ExtraIO.pinMode(SX1509_PIR1_PIN,    INPUT);
  ExtraIO.pinMode(SX1509_PIR2_PIN,    INPUT);
  ExtraIO.pinMode(SX1509_REED_PIN,    INPUT_PULLUP);
  ExtraIO.pinMode(SX1509_BUTTON_PIN,  INPUT_PULLUP);
  ExtraIO.pinMode(SX1509_BUZZER1_PIN, OUTPUT, LOW);
  ExtraIO.pinMode(SX1509_BUZZER2_PIN, OUTPUT, LOW);
  ExtraIO.pinMode(SX1509_LOCK_PIN,    OUTPUT, HIGH);

  ExtraIO.digitalWrite(SX1509_LOCK_PIN, HIGH);

  ExtraIO.debounceTime(16);
  ExtraIO.debouncePin(SX1509_PIR1_PIN);
  ExtraIO.debouncePin(SX1509_PIR2_PIN);
  ExtraIO.debouncePin(SX1509_REED_PIN);
  ExtraIO.debouncePin(SX1509_BUTTON_PIN);
 
  ExtraIO.enableInterrupt(SX1509_PIR1_PIN,   CHANGE);
  ExtraIO.enableInterrupt(SX1509_PIR2_PIN,   CHANGE);
  ExtraIO.enableInterrupt(SX1509_REED_PIN,   CHANGE);
  ExtraIO.enableInterrupt(SX1509_BUTTON_PIN, CHANGE);
  
  uint16_t discard;
  ExtraIO.getAndClearInterrupts(&discard);

  keypad.addStatedEventListener(keyEventListener);
}

void IO_Init() {

  pinMode(SX1509_INT_PIN, INPUT_PULLUP);
 
  bool ok = false;
  for(int i = 0; i < 5 && !ok; i++)
  {
    ok = ExtraIO.begin(SX1509_ADDRESS);
    if(!ok) delay(200);
  }

  if(!ok)
  {
    DEBUG_PRINTLN("IO_Init - SX1509 Init Failed!");
    printLog("SX1509 Init Failed! Rebooting...");
    delay(5000);
    ESP.restart();
  }

  DEBUG_PRINTLN("IO_Init - SX1509 Init Successful");
  printLog("SX1509 Init Successful");

  IO_Configure();
  IO_Service(true);
}

void IO_Reinit() {

  DEBUG_PRINTLN("IO_Reinit - recovering the I2C bus and re-initialising the SX1509");
  I2C_Recover();
  if(ExtraIO.begin(SX1509_ADDRESS))
  {
    buzzer1_off_at = buzzer2_off_at = 0;
    IO_Configure();
    IO_Service(true);
  }
}

void IO_Service(bool force)
{
  static bool resync = false;
  if (!force && !resync && digitalRead(SX1509_INT_PIN) != LOW) return;

  uint16_t src = 0;
  if (!force && !resync)
  {
    if (!ExtraIO.getAndClearInterrupts(&src)) return;
    if (!(src & IO_INT_MASK)) return;
  }

  KeypadIRQ_OnInterrupt(src);

  uint16_t in;
  if (!ExtraIO.getInputs(&in)) { resync = true; return; }
  resync = false;

  static uint16_t last = 0xFFFF;
  uint16_t changed = force ? 0xFFFF : (in ^ last);
  last = in;

  PIR_Update(in & (1u << SX1509_PIR1_PIN), in & (1u << SX1509_PIR2_PIN));
  Reed_Update(in & (1u << SX1509_REED_PIN));
  if (!force && (changed & (1u << SX1509_BUTTON_PIN)))
    Button_Update(!(in & (1u << SX1509_BUTTON_PIN)));
}

void I2C_Recover() {

  Wire.end();
  pinMode(I2C_SDA, INPUT_PULLUP);
  pinMode(I2C_SCL, OUTPUT_OPEN_DRAIN);
  digitalWrite(I2C_SCL, HIGH);
  for(int i = 0; i < 9 && digitalRead(I2C_SDA) == LOW; i++)     // a slave stuck mid-byte lets go after <= 9 clocks
  {
    digitalWrite(I2C_SCL, LOW);  delayMicroseconds(5);
    digitalWrite(I2C_SCL, HIGH); delayMicroseconds(5);
  }
  pinMode(I2C_SDA, OUTPUT_OPEN_DRAIN);                          // then send a STOP
  digitalWrite(I2C_SDA, LOW);  delayMicroseconds(5);
  digitalWrite(I2C_SCL, HIGH); delayMicroseconds(5);
  digitalWrite(I2C_SDA, HIGH); delayMicroseconds(5);
  Wire.setTimeOut(10);
  Wire.begin(I2C_SDA, I2C_SCL);
  Wire.setClock(100000);
}

void IO_Watchdog() {

  static unsigned long last = 0, last_recover = 0;
  static uint8_t bad = 0;
  if(millis() - last < 500) return;
  last = millis();

  uint16_t dir;
  if(!ExtraIO.getDirections(&dir))                     // the chip did not answer
  {
    bad++;
    if(bad >= 2) io_healthy = false;                   // stop hammering a dead bus with keypad scans
    if(bad >= 4 && millis() - last_recover > 5000) { last_recover = millis(); bad = 0; IO_Reinit(); }
    return;
  }
  bad = 0;
  io_healthy = true;

  // it answers, but did it forget its configuration (brown-out / reset)? outputs must be outputs,
  // our interrupt pins must be inputs.
  if((dir & IO_OUT_MASK) != 0 || (dir & IO_INT_MASK) != IO_INT_MASK)
  {
    DEBUG_PRINTLN("IO_Watchdog - SX1509 lost its configuration, restoring it");
    IO_Configure();
    IO_Service(true);
  }
}

bool LIDAR_Init() {

  Wire.beginTransmission(0x50);
  if(Wire.endTransmission() != 0)
  {
    DEBUG_PRINTLN("LIDAR_Init - LIDAR not found at 0x50, disabled");
    return false;
  }
  LIDAR.begin(0x50);
  LIDAR.setMode(LIDAR.eContinuous, LIDAR.eHigh);
  LIDAR.start();
  return true;
}

int lidar_median_read() {

  int samples[LIDAR_SAMPLES];
  int valid = 0;

  for (int i = 0; i < LIDAR_SAMPLES; i++) {
    int d = LIDAR.getDistance();
    if (d > 0 && d < 8000) samples[valid++] = d;
    delay(10); // small gap between samples — keeps I2C happy
  }

  if (valid == 0) return -1;
  if (valid == 1) return samples[0];

  // Simple sort for small N
  for (int i = 0; i < valid - 1; i++)
    for (int j = i + 1; j < valid; j++)
      if (samples[j] < samples[i]) { int t = samples[i]; samples[i] = samples[j]; samples[j] = t; }

  return samples[valid / 2];
}

void LIDAR_Handler() {

  if(millis() - last_lidar_read < lidar_read_interval) return;
  last_lidar_read = millis();

  int dist = lidar_median_read();
  if(dist < 0) return;

  // Bootstrap
  if(lidar_baseline < 0) 
  {
    lidar_baseline     = dist;
    lidar_last_reading = dist;
    DEBUG_PRINT("LIDAR_Handler - Baseline initialised: ");
    DEBUG_PRINT(lidar_baseline);
    DEBUG_PRINTLN("mm");
    return;
  }

  int delta_from_baseline = abs(dist - lidar_baseline);
  bool reading_is_normal  = (delta_from_baseline < LIDAR_BASELINE_MARGIN);

  // ── Only update baseline when stable AND no presence active
  // Prevents the baseline from chasing the environment during an event
  if(reading_is_normal && !LIDAR_presence) 
  {
    lidar_baseline = (int)(LIDAR_BASELINE_ALPHA * dist + (1.0f - LIDAR_BASELINE_ALPHA) * lidar_baseline);
  }

  bool suspicious = (delta_from_baseline > LIDAR_CHANGE_THRESHOLD);

  if(suspicious) 
  {
    lidar_last_trigger_ms = millis();
    if(!LIDAR_presence) 
    {
      LIDAR_presence = true;
      Lidar.setState(true);
      DEBUG_PRINTLN("LIDAR_Handler - Presence detected.");
    }
  } 
  else 
  {
    if(LIDAR_presence && (millis() - lidar_last_trigger_ms > LIDAR_PRESENCE_HOLD_MS)) {
      LIDAR_presence = false;
      Lidar.setState(false);
      DEBUG_PRINTLN("LIDAR_Handler - Presence cleared.");
    }
  }

  lidar_last_reading = dist;

  #if SERIAL_DEBUG != 0
    //Serial.printf("LIDAR_Handler - dist=%d mm  baseline=%d mm  delta=%d  present=%s\n", dist, lidar_baseline, delta_from_baseline, LIDAR_presence ? "YES" : "no");
  #endif
}

void PIR_Update(bool hall_motion, bool room_motion) {

  if(hall_motion != pir1_level) { pir1_level = hall_motion; pir_last_trigger_ms1 = millis(); }
  if(room_motion != pir2_level) { pir2_level = room_motion; pir_last_trigger_ms2 = millis(); }
 
  if(hall_motion && !Hall_presence)
  {
    Hall_presence = true;
    PIR1.setState(true);
    DEBUG_PRINTLN("PIR_Update - Hall Presence detected");
  }
  if(room_motion && !Room_presence)
  {
    Room_presence = true;
    PIR2.setState(true);
    DEBUG_PRINTLN("PIR_Update - Room Presence detected");
  }
}

void PIR_HoldTimers() {

  if(Hall_presence && !pir1_level && millis() - pir_last_trigger_ms1 > PIR_PRESENCE_HOLD_MS)
  {
    Hall_presence = false;
    PIR1.setState(false);
    DEBUG_PRINTLN("PIR_HoldTimers - Hall Presence cleared");
  }
  if(Room_presence && !pir2_level && millis() - pir_last_trigger_ms2 > PIR_PRESENCE_HOLD_MS)
  {
    Room_presence = false;
    PIR2.setState(false);
    DEBUG_PRINTLN("PIR_HoldTimers - Room Presence cleared");
  }
}

void Reed_Update(bool open) {

  if(open != Door_open)
  {
    Door_open = open;
    Reed.setState(open);
    Update_Screen = true;
    DEBUG_PRINTLN(open ? "Reed_Update - Door Opened" : "Reed_Update - Door Closed");
  }
}

void Button_Update(bool pressed)
{
  if(pressed)
  {
    DEBUG_PRINTLN("Button_Update - BTN PRESS!");
    AutomationTO_HA.setValue((int8_t)10);
    UnlockDoor_Now = true;
  }
}

void AHT10_Handler() {

  if(millis() - last_aht10_read < aht10_read_interval) return;
  last_aht10_read = millis();

  float temperature = AHT10.GetTemperature();
  float humidity = AHT10.GetHumidity();

  Temp.setValue(temperature);
  Humd.setValue(humidity);
}

