void HAButtonsHandler(HAButton* sender) {

  if(sender == &DevModeCMD) 
  {
    DEBUG_PRINTLN("HAButtonsHandler - Restarting into Dev Mode");
    reboot_devmode = true;
    UpdateEEPROM();
    delay(1000);
    ESP.restart();
  }
  if(sender == &RebootCMD) 
  {
    ESP.restart();
  } 
  else if(sender == &UnlockDoorCMD) 
  {
    DEBUG_PRINTLN("HAButtonsHandler - Unlock Command Received");
    UnlockDoor_Now = true;
  } 
  else if(sender == &IntercomRINGCMD) 
  {
    DEBUG_PRINTLN("HAButtonsHandler - Intercom Ring Command Received");
    //todo
  }
}

void HASwitchHandler(bool state, HASwitch* sender) {

  if(sender == &Buzzer1CMD) 
  {
    if(state) 
    {
      if(!mute) ExtraIO.digitalWrite(SX1509_BUZZER1_PIN, HIGH);
    } 
    else 
    {
      ExtraIO.digitalWrite(SX1509_BUZZER1_PIN, LOW);
    }
  }
  else if(sender == &Buzzer2CMD) 
  {
    if(state) 
    {
      if(!mute) ExtraIO.digitalWrite(SX1509_BUZZER2_PIN, HIGH);
    } 
    else 
    {
      ExtraIO.digitalWrite(SX1509_BUZZER2_PIN, LOW);
    }
  }
  else if(sender == &MuteCMD) 
  {
    if(state) 
    {
      DEBUG_PRINTLN("HASwitchHandler - Muted");
      mute = true;
    } 
    else 
    {
      DEBUG_PRINTLN("HASwitchHandler - Unmuted");
      mute = false;
    }
    UpdateEEPROM();
  }
  else if(sender == &IntercomStartRecv) 
  {
    DEBUG_PRINTLN("HASwitchHandler - Intercom Start Receive Command Received");
    intercom_receiving = state;
  }

  sender->setState(state); // report state back to the Home Assistant
}

void onNumberCommand(HANumeric number, HANumber* sender) {

  /*
    CMD Numbers and their meaning

    ---------From HA---------

    0   - no command, default state
    1   - gate opened
    2   - gate closed
    3   - calling bell rang
    4   - lower stair node LIDAR presence detected
    5   - upper stair node PIR presence detected
    6   - upper stair node LIDAR presence detected
    7   - hallway presence detected
    8   - stop all sounds
    9   - disable keypad unlocking
    10  - enable keypad unlocking
    11  - disable doorlock functionality
    12  - enable doorlock functionality
  */

  //todo rest of this function

  if(!number.isSet()) 
  {
    CMD_fromHA = 0;
  } 
  else 
  {
    CMD_fromHA = number.toInt8();

    if(CMD_fromHA == 1)//gate opened
    {

    }
    else if(CMD_fromHA == 2)//gate closed
    {

    }
    else if(CMD_fromHA == 3)//calling bell rang
    {

    }
    else if(CMD_fromHA == 4)//lower stair node LIDAR presence detected
    {

    }
    else if(CMD_fromHA == 5)//upper stair node PIR presence detected
    {

    }
    else if(CMD_fromHA == 6)//upper stair node LIDAR presence detected
    {

    }
    else if(CMD_fromHA == 7)//hallway presence detected
    {

    }
    else if(CMD_fromHA == 8)//stop all sounds
    {
      DEBUG_PRINTLN("onNumberCommand - Stop all sounds command received");
      ExtraIO.digitalWrite(SX1509_BUZZER1_PIN, LOW);
      ExtraIO.digitalWrite(SX1509_BUZZER2_PIN, LOW);
      buzzer1_off_at = buzzer2_off_at = 0;

      //todo also stop I2S Dac sounds
    }
    else if(CMD_fromHA == 9)//disable keypad unlocking
    {
      DEBUG_PRINTLN("onNumberCommand - Disable keypad unlocking command received");
      if(!disable_keypad_unlocking) 
      {
        disable_keypad_unlocking = true;
        disable_doorlock_functionality = false;
        MENU = 1;
        Generate_Screen = true;
        UpdateEEPROM();
      }
    }
    else if(CMD_fromHA == 10)//enable keypad unlocking
    {
      DEBUG_PRINTLN("onNumberCommand - Enable keypad unlocking command received");
      if(disable_keypad_unlocking) 
      {
        disable_keypad_unlocking = false;
        disable_doorlock_functionality = false;
        MENU = 1;
        Generate_Screen = true;
        UpdateEEPROM();
      }
    }
    else if(CMD_fromHA == 11)//disable doorlock functionality
    {
      DEBUG_PRINTLN("onNumberCommand - Disable doorlock functionality command received");
      if(!disable_doorlock_functionality) 
      {
        disable_doorlock_functionality = true;
        disable_keypad_unlocking = false;
        MENU = 1;
        Generate_Screen = true;
        UpdateEEPROM();
      }
    }
    else if(CMD_fromHA == 12)//enable doorlock functionality
    {
      DEBUG_PRINTLN("onNumberCommand - Enable doorlock functionality command received");
      if(disable_doorlock_functionality) 
      {
        disable_doorlock_functionality = false;
        disable_keypad_unlocking = false;
        MENU = 1;
        Generate_Screen = true;
        UpdateEEPROM();
      }
    }
  }

  sender->setState(number);
}

