void Display_Update_PIN() {

  //clear enteredpin boxes
  tft.fillRect(52, 151, 23, 25, TFT_BLACK);
  tft.fillRect(85, 151, 23, 25, TFT_BLACK);
  tft.fillRect(118, 151, 23, 25, TFT_BLACK);
  tft.fillRect(151, 151, 23, 25, TFT_BLACK);
  tft.fillRect(184, 151, 23, 25, TFT_BLACK);

  if(incorrect_pin && !correct_pin) tft.setTextColor(TFT_RED);
  else if(!incorrect_pin && correct_pin) tft.setTextColor(LIGHT_BLUE);
  else if(!incorrect_pin && !correct_pin) tft.setTextColor(TFT_WHITE);

  tft.setTextSize(3);

  if(PIN[0] > -1) tft.drawString(String(PIN[0]), 56, 153);

  if(PIN[1] > -1) tft.drawString(String(PIN[1]), 89, 153);

  if(PIN[2] > -1) tft.drawString(String(PIN[2]), 122, 153);

  if(PIN[3] > -1) tft.drawString(String(PIN[3]), 155, 153);

  if(PIN[4] > -1) tft.drawString(String(PIN[4]), 188, 153);
}

void Display_Update_Doorstatus() {

  //clear doorstatus
  tft.fillRect(16, 44, 206, 59, TFT_BLACK);

  if(!Door_open && !UnlockingStarted)
  {
    // lock_state_panel
    tft.fillRect(16, 44, 206, 59, FAINT_ORANGE);

    // lock_state
    tft.setTextColor(RED);
    tft.setTextSize(4);
    tft.drawString("LOCKED", 50, 60);
  } 
  else if(!Door_open && UnlockingStarted)
  {
    // lock_state_panel
    tft.fillRect(16, 44, 206, 59, FAINT_GREEN);

    // lock_state
    tft.setTextColor(GREEN);
    tft.setTextSize(4);
    tft.drawString("UNLOCKED", 26, 60);
  }
  else if(Door_open)
  {
    // lock_state_panel
    tft.fillRect(16, 44, 206, 59, FAINT_BLUE);

    // lock_state
    tft.setTextColor(LIGHT_BLUE);
    tft.setTextSize(4);
    tft.drawString("OPENED", 50, 60);
  }

  Update_Screen = false;
}

void keyEventListener(KeypadEvent key, KeyState kpadState) {

  if(!TransmitAudioBTNHeld && kpadState == PRESSED && key == '*')
  {
    Outdoor_Beep(100);
    TransmitAudioBTNHeld = true;
  }
  else if(TransmitAudioBTNHeld && kpadState == RELEASED && key == '*')
  {
    Outdoor_Beep(100);
    TransmitAudioBTNHeld = false;
  }
  else if(kpadState == PRESSED && key == '#')
  {
    Outdoor_Beep(100);
    Pulse_IntercomCalling(1000);
  }
  else if(kpadState == PRESSED && key != '#' && key != '*' && !incorrect_pin && !disable_keypad_unlocking)
  {
    Outdoor_Beep(80);

    if(disable_doorlock_functionality)
    {
      DEBUG_PRINTLN("keyEventListener - doorlock off, unlocking door with any pin.");
      doorlockFX.alertSweep(hueColor(HUE_GREEN), 4000);
      UnlockDoor_Now = true;
      return;
    }

    int digit = key - '0';

    for(int i = 0; i < 5; i++)
    {
      if(PIN[i] == -1)
      {
        PIN[i] = digit;
        break;
      }
    }

    DEBUG_PRINTLN("keyEventListener - PIN entered: [" + String(PIN[0]) + "][" + String(PIN[1]) + "][" + String(PIN[2]) + "][" + String(PIN[3]) + "][" + String(PIN[4]) + "]");
    Display_Update_PIN();

    if(PIN[0] > -1 && PIN[1] > -1 && PIN[2] > -1 && PIN[3] > -1 && PIN[4] > -1)
    {
      if(Check_PIN())
      {
        DEBUG_PRINTLN("keyEventListener - Correct PIN entered.");
        AutomationTO_HA.setValue((int8_t)1);
        correct_pin = true;
        doorlockFX.alertSweep(hueColor(HUE_GREEN), 4000);
        UnlockDoor_Now = true;
        reset_pin_at = millis() + 4000;
        Display_Update_PIN();
      }
      else
      {
        DEBUG_PRINTLN("keyEventListener - Incorrect PIN entered.");
        AutomationTO_HA.setValue((int8_t)2);
        Outdoor_Beep(500);
        incorrect_pin = true;
        doorlockFX.alertFlash(hueColor(HUE_RED), 20);
        reset_pin_at = millis() + 4000;
        Display_Update_PIN();
      }
    }
  }

  DEBUG_PRINT("keyEventListener - Key ");
  DEBUG_PRINT(key);
  switch(kpadState)
  {
    case PRESSED:    
      DEBUG_PRINTLN(" PRESSED.");
      break;
    case HOLD:
      DEBUG_PRINTLN(" HOLD.");
      break;
    case RELEASED:
      DEBUG_PRINTLN(" RELEASED.");
      break;
    case IDLE:
      DEBUG_PRINTLN(" IDLE.");
      break;
  }
}

//========================================================================================================================================
//======================= Intercom Functions ========================
//========================================================================================================================================

void Intercom_Init() {
  m_output_buffer = new OutputBuffer(300 * 16);
  m_input = new ADCSampler(ADC_UNIT_1, ADC_MIC_CHANNEL, i2s_adc_config);
  m_output = new I2SOutput(I2S_NUM_1, i2s_speaker_pins);
  m_transport = new UdpTransport(m_output_buffer);
  m_transport->set_header(TRANSPORT_HEADER_SIZE, transport_header);

  m_transport->begin();
  m_output->start(SAMPLE_RATE);
  m_output_buffer->flush();

  xTaskCreatePinnedToCore(Intercom_Task,  "Intercom_Task", 8192, NULL, 1, NULL, 0);
}

void Intercom_Task(void *param) {

  int16_t *samples = reinterpret_cast<int16_t *>(malloc(sizeof(int16_t) * 128));

  while(true)
  {
    if(TransmitAudioBTNHeld)
    {
      DEBUG_PRINTLN("Intercom_Task - Started transmitting");

      // transmit for at least 1 second or while the button is pushed
      m_output->stop();
      m_input->start();

      unsigned long start_time = millis();
      uint32_t total = 0;
      while(millis() - start_time < 1000 || TransmitAudioBTNHeld)
      {
        int n = m_input->read(samples, 128);
        for(int i = 0; i < n; i++) m_transport->add_sample(samples[i]);
        total += n;
      }
      unsigned long ms = millis() - start_time;

      m_transport->flush();
      m_input->stop();
      m_output->start(SAMPLE_RATE);
      Serial.printf("Sent %u samples in %lu ms = %.0f Hz\n", (unsigned)total, ms, total * 1000.0 / ms);
      DEBUG_PRINTLN("Intercom_Task - Finished transmitting");
    }

    if(intercom_receiving)
    {
      DEBUG_PRINTLN("Intercom_Task - Started Receiving");
      while(!TransmitAudioBTNHeld && intercom_receiving)
      {
        m_output_buffer->remove_samples(samples, 128); // read from the output buffer (which should be getting filled by the transport)
        m_output->write(samples, 128); // and send the samples to the speaker
      }
      DEBUG_PRINTLN("Intercom_Task - Finished Receiving");
      m_output_buffer->flush();
    }
    vTaskDelay(pdMS_TO_TICKS(10));
  }
}

void Pulse_IntercomCalling(uint16_t ms) {
  Outdoor_Beep(100);
  IntercomCalling.setState(true);
  intercom_calling_off_at = millis() + ms;
  if(intercom_calling_off_at == 0) intercom_calling_off_at = 1;
}